        var vpcEncryptionControlExclusionsResult = CreateVpcEncryptionControlExclusions();
        factoryAction?.Invoke(vpcEncryptionControlExclusionsResult);

        return vpcEncryptionControlExclusionsResult;
    }

    private Humidifier.EC2.VPCTypes.VpcEncryptionControlExclusions CreateVpcEncryptionControlExclusions()
    {
