        base.CreateChildren(result);

        result.ElasticFileSystem ??= ElasticFileSystemFactory?.Build();
        result.VpcLattice ??= VpcLatticeFactory?.Build();
        result.VpcPeering ??= VpcPeeringFactory?.Build();
        result.InternetGateway ??= InternetGatewayFactory?.Build();
        result.EgressOnlyInternetGateway ??= EgressOnlyInternetGatewayFactory?.Build();
        result.VirtualPrivateGateway ??= VirtualPrivateGatewayFactory?.Build();
        result.NatGateway ??= NatGatewayFactory?.Build();
